<?php
declare(strict_types=1);
require __DIR__ . '/includes/app.php';

try {
    $person = profile();
    $certificates = records('certificates', 'year DESC, id DESC');
    $photos = records('gallery');
    $posts = array_values(array_filter(records('posts', 'created_at DESC'), fn (array $post): bool => (bool) $post['is_published']));
} catch (Throwable $error) {
    http_response_code(503);
    require __DIR__ . '/includes/database-error.php';
    exit;
}
$name = $person['full_name'] ?? 'Tu nombre completo';
$initials = implode('', array_map(function (string $word): string {
    preg_match('/^./u', $word, $match);
    return $match[0] ?? '';
}, array_slice(preg_split('/\s+/u', $name) ?: [], 0, 2)));
?>
